import {
  SchemaDocument,
  TypeDefinition,
  TypeNode,
  FieldDefinition,
} from '../ir/types';

export interface GoGeneratorOptions {
  packageName?: string;
}

/**
 * Generates idiomatic Go structs and types with json tags.
 */
export function generateGo(
  doc: SchemaDocument,
  options: GoGeneratorOptions = { packageName: 'models' }
): string {
  const lines: string[] = [
    '// Code generated by TypeBridge. DO NOT EDIT.',
    `package ${options.packageName}`,
    '',
    'import (',
    '\t"time"',
    ')',
    '',
  ];

  for (const def of doc.definitions) {
    if (def.kind === 'struct') {
      lines.push(generateGoStruct(def));
      lines.push('');
    } else if (def.kind === 'enum') {
      lines.push(generateGoEnum(def));
      lines.push('');
    } else if (def.kind === 'alias') {
      lines.push(`type ${def.name} = ${mapTypeToGo(def.targetType)}`);
      lines.push('');
    }
  }

  return lines.join('\n');
}

function generateGoStruct(def: Extract<TypeDefinition, { kind: 'struct' }>): string {
  const lines: string[] = [];
  if (def.description) {
    lines.push(`// ${def.name} - ${def.description}`);
  }
  lines.push(`type ${def.name} struct {`);

  for (const field of def.fields) {
    const goFieldName = toPascalCase(field.name);
    const goType = mapTypeToGo(field.type);
    const jsonTag = field.optional
      ? `\`json:"${field.name},omitempty"\``
      : `\`json:"${field.name}"\``;

    if (field.description) {
      lines.push(`\t// ${field.description}`);
    }

    if (field.optional) {
      lines.push(`\t${goFieldName} *${goType} ${jsonTag}`);
    } else {
      lines.push(`\t${goFieldName} ${goType} ${jsonTag}`);
    }
  }

  lines.push('}');
  return lines.join('\n');
}

function generateGoEnum(def: Extract<TypeDefinition, { kind: 'enum' }>): string {
  const lines: string[] = [];
  if (def.description) {
    lines.push(`// ${def.name} - ${def.description}`);
  }
  lines.push(`type ${def.name} string`);
  lines.push('');
  lines.push('const (');

  for (const val of def.values) {
    const constName = `${def.name}${toPascalCase(val.name)}`;
    lines.push(`\t${constName} ${def.name} = "${val.value}"`);
  }

  lines.push(')');
  return lines.join('\n');
}

function mapTypeToGo(node: TypeNode): string {
  switch (node.kind) {
    case 'primitive':
      switch (node.primitive) {
        case 'string':
          return 'string';
        case 'number':
          return 'float64';
        case 'integer':
          return 'int64';
        case 'boolean':
          return 'bool';
        case 'date':
          return 'time.Time';
        case 'uuid':
          return 'string';
        case 'null':
          return 'any';
        case 'any':
        default:
          return 'any';
      }
    case 'reference':
      return node.name;
    case 'array':
      return `[]${mapTypeToGo(node.elementType)}`;
    case 'map':
      return `map[${mapTypeToGo(node.keyType)}]${mapTypeToGo(node.valueType)}`;
    case 'optional':
      return mapTypeToGo(node.innerType);
    case 'union':
      return 'any';
    case 'literal':
      return typeof node.value === 'string' ? 'string' : typeof node.value;
    default:
      return 'any';
  }
}

function toPascalCase(str: string): string {
  return str
    .replace(/(?:^|_|[- ])(\w)/g, (_, c) => c.toUpperCase());
}
